  <input id="wavelengthScrubInput" type="range" min="200" max="400" step="1" value="217"
    oninput="document.getElementById('wavelengthScrubVal').value=this.value;update_wavelengthScrub(+this.value)">
</label>
<label>Region emphasis
  <select id="regionViewInput" onchange="toggle_regionView(this.value)" style="font-size:11px;padding:2px">
    <option>Full spectrum</option>
