  ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}
function arrow(ctx, x1, y1, x2, y2, lw, color) {
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hd = lw * 3.2;
  ctx.save();
  ctx.strokeStyle = color; ctx.fillStyle = color;
  ctx.lineWidth = lw; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2 - Math.cos(ang) * hd * 0.7, y2 - Math.sin(ang) * hd * 0.7);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - Math.cos(ang - 0.42) * hd, y2 - Math.sin(ang - 0.42) * hd);
  ctx.lineTo(x2 - Math.cos(ang + 0.42) * hd, y2 - Math.sin(ang + 0.42) * hd);
  ctx.closePath(); ctx.fill();
  ctx.restore();
}
function drawLambdaMax(ctx, x, y, fs) {
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  var cur = x;
  ctx.font = 'italic ' + fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, 'λ', cur, y); cur += ctx.measureText('λ').width;
  ctx.font = 'italic ' + (fs * 0.72).toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, 'max', cur, y + fs * 0.20); cur += ctx.measureText('max').width;
  ctx.font = fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, ' = 217 nm', cur, y);
}

/* ── Background: pink gradient + region emphasis ────────────────────────── */
var bgPlugin = {
  id: 'bgPlugin',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea, xs = chart.scales.x;
    if (!a) return;
    ctx.save();
    var g = ctx.createLinearGradient(0, a.top, 0, a.bottom);
    g.addColorStop(0, 'rgba(232,62,140,0.30)');
    g.addColorStop(0.45, 'rgba(232,62,140,0.15)');
    g.addColorStop(1, 'rgba(232,62,140,0.00)');
    ctx.fillStyle = g;
    ctx.fillRect(a.left, a.top, a.width, a.height);

    if (state.region !== 'Full spectrum') {
      var b = regionBounds();
      var x0 = xs.getPixelForValue(b[0]), x1 = xs.getPixelForValue(b[1]);
      ctx.fillStyle = 'rgba(255,255,255,0.66)';
      if (x0 > a.left) ctx.fillRect(a.left, a.top, x0 - a.left, a.height);
      if (x1 < a.right) ctx.fillRect(x1, a.top, a.right - x1, a.height);
      ctx.fillStyle = 'rgba(120,124,140,0.10)';
      if (x0 > a.left) ctx.fillRect(a.left, a.top, x0 - a.left, a.height);
      if (x1 < a.right) ctx.fillRect(x1, a.top, a.right - x1, a.height);
      ctx.fillStyle = 'rgba(232,62,140,0.10)';
      ctx.fillRect(x0, a.top, x1 - x0, a.height);
      ctx.strokeStyle = 'rgba(232,62,140,0.5)';
      ctx.lineWidth = 1; ctx.setLineDash([4, 3]);
      ctx.strokeRect(x0 + 0.5, a.top + 0.5, Math.max(1, x1 - x0 - 1), a.height - 1);
      ctx.setLineDash([]);
    }
    ctx.restore();
  }
};

/* ── Overlay: marker, annotation, readout chip, axis titles + arrows ────── */
var overlayPlugin = {
  id: 'overlayPlugin',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
    if (!a) return;
    var S = Math.min(a.width, a.height);
    var fs = clamp(9, 15, S * 0.042);

    /* λmax annotation */
    ctx.save();
    drawLambdaMax(ctx, xs.getPixelForValue(221), ys.getPixelForValue(0.925), fs);
    ctx.restore();

    /* marker + dropline */
    var lam = state.lambda, A = absorb(lam);
    var px = xs.getPixelForValue(lam), py = ys.getPixelForValue(A);
    ctx.save();
    ctx.setLineDash([3, 3]);
    ctx.strokeStyle = 'rgba(229,0,126,0.45)';
    ctx.lineWidth = clamp(0.8, 1.6, S * 0.004);
    ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, a.bottom); ctx.stroke();
    ctx.setLineDash([]);
    var r = clamp(3, 6.5, S * 0.016);
    ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fillStyle = MAIN; ctx.fill();
    ctx.lineWidth = clamp(1, 2, S * 0.005); ctx.strokeStyle = '#fff'; ctx.stroke();
    ctx.restore();

    /* readout chip (top-right of plot area) */
    ctx.save();
    var cfs = clamp(9, 13, S * 0.036);
    ctx.font = '600 ' + cfs.toFixed(1) + 'px system-ui, sans-serif';
    var txt = 'λ = ' + lam.toFixed(0) + ' nm   A = ' + (A < 0.1 ? A.toFixed(3) : A.toFixed(2));
    var tw = ctx.measureText(txt).width;
    var pw = tw + cfs * 1.4, ph = cfs * 1.9;
    var cx = a.right - pw - cfs * 0.6, cy = a.top + cfs * 0.6;
    ctx.fillStyle = 'rgba(255,255,255,0.93)';
    ctx.strokeStyle = MAIN; ctx.lineWidth = 1;
    roundRect(ctx, cx, cy, pw, ph, ph * 0.28); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#b3006b';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(txt, cx + cfs * 0.7, cy + ph / 2);
    ctx.restore();
  },
  afterDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea;
    if (!a) return;
    var S = Math.min(a.width, a.height);
    var tfs = clamp(9, 15, S * 0.044);
    var lw = clamp(1.2, 2.6, S * 0.007);

    /* x-axis title + right arrow */
    ctx.save();
    ctx.font = tfs.toFixed(1) + 'px system-ui, "Segoe UI", sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    var t = 'Wavelength (nm)';
    var tw = ctx.measureText(t).width;
    var gap = tfs * 0.7, alen = tfs * 3.2;
    var total = tw + gap + alen;
    var sx = (a.left + a.right) / 2 - total / 2;
    var by = chart.height - tfs * 0.9;
    ctx.fillStyle = '#111';
    ctx.fillText(t, sx, by);
    arrow(ctx, sx + tw + gap, by, sx + tw + gap + alen, by, lw, MAIN);
    ctx.restore();

    /* y-axis title (rotated) + up arrow */
    ctx.save();
    var yx = Math.max(tfs * 0.9, (chart.scales.y.left || 0) * 0.35);
    ctx.translate(yx, a.top + a.height * 0.66);
    ctx.rotate(-Math.PI / 2);
    ctx.font = tfs.toFixed(1) + 'px system-ui, "Segoe UI", sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#111';
    ctx.fillText('Absorbance', 0, 0);
    ctx.restore();
    arrow(ctx, yx, a.top + a.height * 0.34, yx, a.top + a.height * 0.09, lw, MAIN);
  }
};

/* ── Chart ──────────────────────────────────────────────────────────────── */
var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      label: '1,3-butadiene',
      data: pts,
      parsing: false,
      borderColor: MAIN,
      backgroundColor: 'transparent',
      pointRadius: 0,
      pointHitRadius: 0,
      borderJoinStyle: 'round',
      borderCapStyle: 'round',
      tension: 0,
      borderWidth: function (c) {
        var a = c.chart.chartArea;
        var S = a ? Math.min(a.width, a.height) : 300;
        return clamp(1.4, 3, S * 0.008);
      },
      segment: {
        borderColor: function (c) {
          var mid = (c.p0.parsed.x + c.p1.parsed.x) / 2;
          return inRegion(mid) ? MAIN : DIM;
        }
      }
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    layout: { padding: { left: 46, right: 16, top: 14, bottom: 40 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: 200, max: 400,
        grid: { display: false, drawTicks: true, tickColor: '#000' },
        border: { color: '#000', width: 1 },
        ticks: {
          color: '#000', stepSize: 20, autoSkip: false,
          font: { size: 13, family: 'system-ui, sans-serif' },
          padding: 4
        },
        title: { display: false }
      },
      y: {
        min: 0, max: 1,
        grid: { display: false, drawTicks: true, tickColor: '#000' },
        border: { color: '#000', width: 1 },
        ticks: {
          color: '#000', stepSize: 0.2,
          font: { size: 13, family: 'system-ui, sans-serif' },
          padding: 4,
          callback: function (v) { return v === 0 ? '0' : Number(v).toFixed(1); }
        },
        title: { display: false }
      }
    }
  },
  plugins: [bgPlugin, overlayPlugin]
});
window.__markRendered();

/* ── Interaction handlers ───────────────────────────────────────────────── */
function syncReadout() {
  var A = absorb(state.lambda);
  var el = document.getElementById('uiReadout');
  if (el) el.textContent = 'λ = ' + state.lambda.toFixed(0) + ' nm → A = ' +
    (A < 0.1 ? A.toFixed(3) : A.toFixed(2)) +
    (Math.abs(state.lambda - 217) <= 1 ? '  (λmax)' : '');
}
function update_wavelengthScrub(v) {
  state.lambda = +v;
  syncReadout();
  chart.update('none');
}
function toggle_regionView(v) {
  state.region = v;
  chart.update('none');
}
function trigger_jumpPeak() {
  var i = document.getElementById('wavelengthScrubInput');
  i.value = 217;
  document.getElementById('wavelengthScrubVal').value = 217;
  update_wavelengthScrub(217);
  showPopup('λmax = 217 nm',
    'The curve reaches its single highest absorbance at 217 nm. This π→π* transition of the conjugated diene is what λmax reports; with A, path length and concentration it gives the molar absorptivity ε = A/(c·l).');
}

/* ── Hover / click ──────────────────────────────────────────────────────── */
canvas.addEventListener('mousemove', function (e) {
  var a = chart.chartArea; if (!a) return;
  var rect = canvas.getBoundingClientRect();
  var px = e.clientX - rect.left;
  if (px < a.left || px > a.right) { hideTooltip(); canvas.style.cursor = 'default'; return; }
  var l = chart.scales.x.getValueForPixel(px);
  canvas.style.cursor = 'pointer';
  showTooltip('λ = ' + l.toFixed(0) + ' nm · A = ' + absorb(l).toFixed(3), e);
});
canvas.addEventListener('mouseleave', hideTooltip);
canvas.addEventListener('click', function (e) {
  var a = chart.chartArea; if (!a) return;
  var rect = canvas.getBoundingClientRect();
  var px = e.clientX - rect.left;
  if (px < a.left || px > a.right) return;
  var l = Math.round(chart.scales.x.getValueForPixel(px));
  document.getElementById('wavelengthScrubInput').value = l;
  document.getElementById('wavelengthScrubVal').value = l;
  update_wavelengthScrub(l);
  var A = absorb(l);
  var msg;
  if (l < 205) msg = 'Near the short-wavelength edge the band is already rising steeply — absorbance here is on the flank of the 217 nm maximum, not a separate feature.';
  else if (l <= 235) msg = 'You are inside the absorption band. Absorbance changes very fast with wavelength here, which is why λmax must be read at the crest rather than anywhere on the slope.';
  else msg = 'Past ~250 nm 1,3-butadiene is essentially transparent: absorbance is a flat, near-zero tail. Extending conjugation would shift a new peak into this window.';
  showPopup('λ = ' + l + ' nm, A = ' + (A < 0.1 ? A.toFixed(3) : A.toFixed(2)), msg);
});

/* ── Resize: scale tick fonts ───────────────────────────────────────────── */
document.addEventListener('fig-resize', function (e) {
  var s = Math.min(e.detail.width, e.detail.height * 1.9);
  var fsz = clamp(8, 14, s * 0.021);
  chart.options.scales.x.ticks.font = { size: fsz, family: 'system-ui, sans-serif' };
  chart.options.scales.y.ticks.font = { size: fsz, family: 'system-ui, sans-serif' };
  chart.options.layout.padding.left = clamp(30, 52, s * 0.07);
  chart.options.layout.padding.bottom = clamp(26, 44, s * 0.06);
  chart.update('none');
});

/* ── Demo step player ───────────────────────────────────────────────────── */
var steps = [
  {
    title: 'The whole spectrum',
    narration: 'Absorbance is plotted against wavelength from 200 to 400 nm. One sharp crest dominates the left edge; the rest of the trace hugs the baseline.',
    state: { regionView: 'Full spectrum', wavelengthScrub: 200 }
  },
  {
    title: 'Climbing toward the maximum',
    narration: 'Drag the marker to 210 nm and the readout climbs fast — absorbance nearly triples over ten nanometers as the π→π* transition comes into resonance.',
    state: { regionView: 'Full spectrum', wavelengthScrub: 210 }
  },
  {
    title: 'λmax = 217 nm',
    narration: 'At the crest the readout reaches its highest value. This single wavelength, λmax, is what is reported for 1,3-butadiene and what is paired with concentration and path length to get molar absorptivity.',
    state: { regionView: 'Peak region (200–240 nm)', wavelengthScrub: 217 }
  },
  {
    title: 'Falling off the peak',
    narration: 'Move past 240 nm and absorbance collapses to below 0.1. The absorption band is narrow: only a small window of wavelengths matches the transition energy.',
    state: { regionView: 'Peak region (200–240 nm)', wavelengthScrub: 245 }
  },
  {
    title: 'The uninformative tail',
    narration: 'Beyond 250 nm the curve is almost flat and almost zero — butadiene is transparent here. A diene with more conjugation would push a peak into this region, which is exactly why the tail is worth watching.',
    state: { regionView: 'Tail region (250–400 nm)', wavelengthScrub: 320 }
  }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var s = steps[curStep];
  var sl = document.getElementById('wavelengthScrubInput');
  sl.value = s.state.wavelengthScrub;
  document.getElementById('wavelengthScrubVal').value = s.state.wavelengthScrub;
  update_wavelengthScrub(s.state.wavelengthScrub);
  var sel = document.getElementById('regionViewInput');
  sel.value = s.state.regionView;
  toggle_regionView(s.state.regionView);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' · ' + s.title;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The UV spectrum of 1,3-butadiene shows a single strong absorption maximum near 217 nm, the λmax used to characterize a conjugated π system and to compute molar absorptivity.
KEY INSIGHT (what students should walk away understanding): λmax is not a label added to the picture — it is the single wavelength where the curve peaks, and for a simple conjugated diene like 1,3-butadiene that peak sits at 217 nm with essentially nothing above 250 nm.
DEMO STEPS: 5 guided steps — implement the step player in #ui

