// @FIGURE_CODE_BEGIN
var MAIN = '#e5007e';
var DIM = 'rgba(229,0,126,0.18)';

function clamp(lo, hi, v) { return Math.max(lo, Math.min(hi, v)); }

/* ── Absorption model ──────────────────────────────────────────────────────
   Broad left flank, rounded crest at ~215 nm (A ≈ 0.87), sharp fall to a
   near-flat tail (0.065 at 250 nm → 0.028 at 400 nm).                       */
function tailA(l) { return 0.065 - 0.0002467 * (l - 250); }
function absorb(l) {
  var s = (l < 215) ? 10.06 : 7.48;
  var pk = 0.80 * Math.exp(-Math.pow(l - 215, 2) / (2 * s * s));
  return tailA(l) + pk;
}

var state = { lambda: 217, region: 'Full spectrum', touched: false };

function regionBounds() {
  if (state.region.indexOf('Peak') === 0) return [200, 240];
  if (state.region.indexOf('Tail') === 0) return [250, 400];
  return [200, 400];
}
function inRegion(x) { var b = regionBounds(); return x >= b[0] && x <= b[1]; }

var pts = [];
for (var L = 200; L <= 400.001; L += 0.5) pts.push({ x: L, y: absorb(L) });

/* ── Canvas ─────────────────────────────────────────────────────────────── */
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

/* ── Helpers ────────────────────────────────────────────────────────────── */
function halo(ctx, txt, x, y, color) {
  ctx.lineJoin = 'round';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(txt, x, y);
}
function arrow(ctx, x1, y1, x2, y2, lw, color) {
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hd = lw * 3.2;
  ctx.save();
  ctx.strokeStyle = color; ctx.fillStyle = color;
  ctx.lineWidth = lw; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2 - Math.cos(ang) * hd * 0.7, y2 - Math.sin(ang) * hd * 0.7);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - Math.cos(ang - 0.42) * hd, y2 - Math.sin(ang - 0.42) * hd);
