// @FIGURE_CODE_BEGIN
var MAIN = '#e5007e';
var DIM = 'rgba(229,0,126,0.18)';

function clamp(lo, hi, v) { return Math.max(lo, Math.min(hi, v)); }

/* ── Absorption model ──────────────────────────────────────────────────────
   Broad left flank, rounded crest at ~215 nm (A ≈ 0.87), sharp fall to a
   near-flat tail (0.065 at 250 nm → 0.028 at 400 nm).                       */
function tailA(l) { return 0.065 - 0.0002467 * (l - 250); }
function absorb(l) {
  var s = (l < 215) ? 10.06 : 7.48;
  var pk = 0.80 * Math.exp(-Math.pow(l - 215, 2) / (2 * s * s));
  return tailA(l) + pk;
}

var state = { lambda: 217, region: 'Full spectrum', touched: false };

function regionBounds() {
  if (state.region.indexOf('Peak') === 0) return [200, 240];
  if (state.region.indexOf('Tail') === 0) return [250, 400];
  return [200, 400];
}
function inRegion(x) { var b = regionBounds(); return x >= b[0] && x <= b[1]; }

var pts = [];
for (var L = 200; L <= 400.001; L += 0.5) pts.push({ x: L, y: absorb(L) });

/* ── Canvas ─────────────────────────────────────────────────────────────── */
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

/* ── Helpers ────────────────────────────────────────────────────────────── */
function halo(ctx, txt, x, y, color) {
  ctx.lineJoin = 'round';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(txt, x, y);
}
function arrow(ctx, x1, y1, x2, y2, lw, color) {
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hd = lw * 3.2;
  ctx.save();
  ctx.strokeStyle = color; ctx.fillStyle = color;
  ctx.lineWidth = lw; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2 - Math.cos(ang) * hd * 0.7, y2 - Math.sin(ang) * hd * 0.7);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - Math.cos(ang - 0.42) * hd, y2 - Math.sin(ang - 0.42) * hd);
  ctx.lineTo(x2 - Math.cos(ang + 0.42) * hd, y2 - Math.sin(ang + 0.42) * hd);
  ctx.closePath(); ctx.fill();
  ctx.restore();
}
function drawLambdaMax(ctx, x, y, fs) {
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  var cur = x;
  ctx.font = 'italic ' + fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, 'λ', cur, y); cur += ctx.measureText('λ').width;
  ctx.font = 'italic ' + (fs * 0.72).toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, 'max', cur, y + fs * 0.20); cur += ctx.measureText('max').width;
  ctx.font = fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  halo(ctx, ' = 217 nm', cur, y);
}
function plotMetric(chart) {
  var a = chart.chartArea;
  if (!a) return 240;
  return Math.min(a.width, a.height * 2);
}

/* ── Layout: force a ~2:1 landscape plot area like the source ───────────── */
var aspectPlugin = {
  id: 'aspectPlugin',
  beforeLayout: function (chart) {
    var w = chart.width, h = chart.height;
    if (!w || !h) return;
    var base = Math.min(w, h * 2);
    var fs = clamp(8.5, 14, base * 0.0225);
    var padL = clamp(30, 58, w * 0.075);
    var padR = clamp(8, 22, w * 0.025);
    var padTopMin = clamp(6, 16, h * 0.03);
    var padBotMin = clamp(28, 62, base * 0.11);
    var plotW = Math.max(60, w - padL - padR);
    var avail = Math.max(40, h - padTopMin - padBotMin);
    var target = Math.min(avail, plotW / 2.05);
    var extra = Math.max(0, avail - target);
    chart.options.layout.padding = {
      left: padL, right: padR,
      top: padTopMin + extra * 0.38,
      bottom: padBotMin + extra * 0.62
    };
    chart.options.scales.x.ticks.font = { size: fs, family: 'system-ui, sans-serif' };
    chart.options.scales.y.ticks.font = { size: fs, family: 'system-ui, sans-serif' };
  }
};

/* ── Background: soft pink gradient (white by mid-height) + region wash ─── */
var bgPlugin = {
  id: 'bgPlugin',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea, xs = chart.scales.x;
    if (!a) return;
    ctx.save();
    var g = ctx.createLinearGradient(0, a.top, 0, a.bottom);
    g.addColorStop(0.00, 'rgba(228,60,140,0.22)');
    g.addColorStop(0.28, 'rgba(228,60,140,0.13)');
    g.addColorStop(0.50, 'rgba(228,60,140,0.045)');
    g.addColorStop(0.64, 'rgba(228,60,140,0.008)');
    g.addColorStop(1.00, 'rgba(228,60,140,0.00)');
    ctx.fillStyle = g;
    ctx.fillRect(a.left, a.top, a.width, a.height);

    if (state.region !== 'Full spectrum') {
      var b = regionBounds();
      var x0 = xs.getPixelForValue(b[0]), x1 = xs.getPixelForValue(b[1]);
      ctx.fillStyle = 'rgba(255,255,255,0.72)';
      if (x0 > a.left) ctx.fillRect(a.left, a.top, x0 - a.left, a.height);
      if (x1 < a.right) ctx.fillRect(x1, a.top, a.right - x1, a.height);
      ctx.fillStyle = 'rgba(228,60,140,0.07)';
      ctx.fillRect(x0, a.top, x1 - x0, a.height);
      ctx.strokeStyle = 'rgba(228,60,140,0.45)';
      ctx.lineWidth = 1; ctx.setLineDash([4, 3]);
      ctx.strokeRect(x0 + 0.5, a.top + 0.5, Math.max(1, x1 - x0 - 1), a.height - 1);
      ctx.setLineDash([]);
    }
    ctx.restore();
  }
};

/* ── Overlay: λmax annotation + (only after interaction) marker ─────────── */
var overlayPlugin = {
  id: 'overlayPlugin',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
    if (!a) return;
    var S = plotMetric(chart);
    var fs = clamp(9, 16, S * 0.036);

    /* λmax = 217 nm — just above / right of the crest, over open whitespace */
    ctx.save();
    drawLambdaMax(ctx, xs.getPixelForValue(221), ys.getPixelForValue(0.925), fs);
    ctx.restore();

    if (!state.touched) return;

    var lam = state.lambda, A = absorb(lam);
    var px = xs.getPixelForValue(lam), py = ys.getPixelForValue(A);

    ctx.save();
    ctx.setLineDash([3, 3]);
    ctx.strokeStyle = 'rgba(229,0,126,0.40)';
    ctx.lineWidth = clamp(0.8, 1.5, S * 0.003);
    ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, a.bottom); ctx.stroke();
    ctx.setLineDash([]);
    var r = clamp(2.6, 5.5, S * 0.012);
    ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fillStyle = MAIN; ctx.fill();
    ctx.lineWidth = clamp(0.9, 1.8, S * 0.004); ctx.strokeStyle = '#fff'; ctx.stroke();

    /* small halo label beside the dot — no box, no corner chip */
    var lfs = clamp(8.5, 12.5, S * 0.028);
    ctx.font = '600 ' + lfs.toFixed(1) + 'px system-ui, sans-serif';
    var txt = lam.toFixed(0) + ' nm · A = ' + (A < 0.1 ? A.toFixed(3) : A.toFixed(2));
    var tw = ctx.measureText(txt).width;
    var tx = px + r + lfs * 0.6, ty = py - lfs * 0.9;
    if (tx + tw > a.right - 4) { ctx.textAlign = 'right'; tx = px - r - lfs * 0.6; }
    else { ctx.textAlign = 'left'; }
    if (ty < a.top + lfs) ty = py + lfs * 1.6;
    ctx.textBaseline = 'middle';
    halo(ctx, txt, tx, ty, '#b3006b');
    ctx.restore();
  },
  afterDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea;
    if (!a) return;
    var S = plotMetric(chart);
    var tfs = clamp(9, 15, S * 0.036);
    var lw = clamp(1.1, 2.4, S * 0.006);

    /* x-axis title + magenta right arrow, anchored under the tick labels */
    ctx.save();
    ctx.font = tfs.toFixed(1) + 'px system-ui, "Segoe UI", sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    var t = 'Wavelength (nm)';
    var tw = ctx.measureText(t).width;
    var gap = tfs * 0.7, alen = tfs * 3.0;
    var total = tw + gap + alen;
    var sx = (a.left + a.right) / 2 - total / 2;
    var by = Math.min(chart.height - tfs * 0.8, a.bottom + tfs * 2.9);
    ctx.fillStyle = '#111';
    ctx.fillText(t, sx, by);
    arrow(ctx, sx + tw + gap, by, sx + tw + gap + alen, by, lw, MAIN);
    ctx.restore();

    /* y-axis title (rotated) + magenta up arrow above it */
    ctx.save();
    var yx = clamp(tfs * 0.85, a.left - tfs * 0.6, (chart.scales.y.left || 0) + tfs * 0.2);
    ctx.translate(yx, a.top + a.height * 0.62);
    ctx.rotate(-Math.PI / 2);
    ctx.font = tfs.toFixed(1) + 'px system-ui, "Segoe UI", sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#111';
    ctx.fillText('Absorbance', 0, 0);
    ctx.restore();
    arrow(ctx, yx, a.top + a.height * 0.36, yx, a.top + a.height * 0.10, lw, MAIN);
  }
};

/* ── Chart ──────────────────────────────────────────────────────────────── */
var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      label: '1,3-butadiene',
      data: pts,
      parsing: false,
      borderColor: MAIN,
      backgroundColor: 'transparent',
      pointRadius: 0,
      pointHitRadius: 0,
      borderJoinStyle: 'round',
      borderCapStyle: 'round',
      tension: 0,
      borderWidth: function (c) {
        var a = c.chart.chartArea;
        var S = a ? Math.min(a.width, a.height * 2) : 300;
        return clamp(1.4, 3, S * 0.0065);
      },
      segment: {
        borderColor: function (c) {
          var mid = (c.p0.parsed.x + c.p1.parsed.x) / 2;
          return inRegion(mid) ? MAIN : DIM;
        }
      }
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    layout: { padding: { left: 46, right: 16, top: 14, bottom: 40 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: 200, max: 400,
        grid: { display: false, drawTicks: true, tickColor: '#000' },
        border: { color: '#000', width: 1 },
        ticks: {
          color: '#000', stepSize: 20, autoSkip: false,
          font: { size: 12, family: 'system-ui, sans-serif' }, padding: 4
        },
        title: { display: false }
      },
      y: {
        min: 0, max: 1,
        grid: { display: false, drawTicks: true, tickColor: '#000' },
        border: { color: '#000', width: 1 },
        ticks: {
          color: '#000', stepSize: 0.2,
          font: { size: 12, family: 'system-ui, sans-serif' }, padding: 4,
          callback: function (v) { return v === 0 ? '0' : Number(v).toFixed(1); }
        },
        title: { display: false }
      }
    }
  },
  plugins: [aspectPlugin, bgPlugin, overlayPlugin]
});
window.__markRendered();

/* ── Interaction handlers ───────────────────────────────────────────────── */
function syncReadout() {
  var el = document.getElementById('uiReadout');
  if (!el) return;
  if (!state.touched) { el.textContent = ''; return; }
  var A = absorb(state.lambda);
  el.textContent = 'λ = ' + state.lambda.toFixed(0) + ' nm → A = ' +
    (A < 0.1 ? A.toFixed(3) : A.toFixed(2)) +
    (Math.abs(state.lambda - 217) <= 1 ? '  (λmax)' : '');
}
function setLambda(v) { state.lambda = +v; syncReadout(); chart.update('none'); }
function update_wavelengthScrub(v) { state.touched = true; setLambda(v); }
function toggle_regionView(v) { state.region = v; chart.update('none'); }
function trigger_jumpPeak() {
  var i = document.getElementById('wavelengthScrubInput');
  i.value = 217;
  document.getElementById('wavelengthScrubVal').value = 217;
  update_wavelengthScrub(217);
  showPopup('λmax = 217 nm',
    'The curve reaches its single highest absorbance at the crest near 215–217 nm. This π→π* transition of the conjugated diene is what λmax reports; combined with A, path length and concentration it gives the molar absorptivity ε = A/(c·l).');
}

/* ── Hover / click ──────────────────────────────────────────────────────── */
canvas.addEventListener('mousemove', function (e) {
  var a = chart.chartArea; if (!a) return;
  var rect = canvas.getBoundingClientRect();
  var px = e.clientX - rect.left;
  if (px < a.left || px > a.right) { hideTooltip(); canvas.style.cursor = 'default'; return; }
  var l = chart.scales.x.getValueForPixel(px);
  canvas.style.cursor = 'pointer';
  showTooltip('λ = ' + l.toFixed(0) + ' nm · A = ' + absorb(l).toFixed(3), e);
});
canvas.addEventListener('mouseleave', hideTooltip);
canvas.addEventListener('click', function (e) {
  var a = chart.chartArea; if (!a) return;
  var rect = canvas.getBoundingClientRect();
  var px = e.clientX - rect.left;
  if (px < a.left || px > a.right) return;
  var l = Math.round(chart.scales.x.getValueForPixel(px));
  document.getElementById('wavelengthScrubInput').value = l;
  document.getElementById('wavelengthScrubVal').value = l;
  update_wavelengthScrub(l);
  var A = absorb(l);
  var msg;
  if (l < 206) msg = 'At the short-wavelength edge the band is already well up its broad left flank — this absorbance belongs to the same 217 nm transition, not to a separate feature.';
  else if (l <= 235) msg = 'You are inside the absorption band. Absorbance changes very fast with wavelength here, which is why λmax must be read at the crest rather than anywhere on the slope.';
  else msg = 'Past ~250 nm 1,3-butadiene is essentially transparent: absorbance is a flat, near-zero tail. Extending the conjugation would shift a new peak into this window.';
  showPopup('λ = ' + l + ' nm, A = ' + (A < 0.1 ? A.toFixed(3) : A.toFixed(2)), msg);
});

document.addEventListener('fig-resize', function () { chart.resize(); });

/* ── Demo step player ───────────────────────────────────────────────────── */
var steps = [
  {
    title: 'The whole spectrum',
    narration: 'Absorbance is plotted against wavelength from 200 to 400 nm. One rounded crest dominates the left edge; the rest of the trace hugs the baseline.',
    state: { regionView: 'Full spectrum', wavelengthScrub: 217, marker: false }
  },
  {
    title: 'Climbing toward the maximum',
    narration: 'Put the marker at 205 nm, then at 210 nm: absorbance climbs fast as the π→π* transition comes into resonance.',
    state: { regionView: 'Full spectrum', wavelengthScrub: 210, marker: true }
  },
  {
    title: 'λmax = 217 nm',
    narration: 'At the crest the readout reaches its highest value. This single wavelength, λmax, is what is reported for 1,3-butadiene and what is paired with concentration and path length to get molar absorptivity.',
    state: { regionView: 'Peak region (200–240 nm)', wavelengthScrub: 217, marker: true }
  },
  {
    title: 'Falling off the peak',
    narration: 'Move past 240 nm and absorbance collapses below 0.1. The band is narrow: only a small window of wavelengths matches the transition energy.',
    state: { regionView: 'Peak region (200–240 nm)', wavelengthScrub: 245, marker: true }
  },
  {
    title: 'The uninformative tail',
    narration: 'Beyond 250 nm the curve is almost flat and almost zero — butadiene is transparent here. More conjugation would push a peak into this region, which is why the tail is worth watching.',
    state: { regionView: 'Tail region (250–400 nm)', wavelengthScrub: 320, marker: true }
  }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var s = steps[curStep];
  var sl = document.getElementById('wavelengthScrubInput');
  sl.value = s.state.wavelengthScrub;
  document.getElementById('wavelengthScrubVal').value = s.state.wavelengthScrub;
  state.touched = !!s.state.marker;
  var sel = document.getElementById('regionViewInput');
  sel.value = s.state.regionView;
  state.region = s.state.regionView;
  setLambda(s.state.wavelengthScrub);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' · ' + s.title;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }
applyStep(0);
// @FIGURE_CODE_END

